import { readFileSync } from 'node:fs';
import path from 'node:path';
import { resolveRunnerPublicationCloseHandoff } from '../framework-development/runner-publication-close-handoff.js';
/** Generated bytes are advisory only while their canonical receipt verifies them. */
export function resolveVerifiedGeneratedOutputPaths(cwd, taskId) {
    try {
        const receipt = JSON.parse(readFileSync(path.join(cwd, '.atm/history/evidence', `${taskId}.runner-sync-receipt.json`), 'utf8'));
        if (!resolveRunnerPublicationCloseHandoff({ cwd, taskId, receipt }).ok)
            return [];
        return receipt.outputInventory.entries.filter((entry) => entry.generated === true)
            .map((entry) => entry.path);
    }
    catch {
        return [];
    }
}
